   155	
   156	interface RatePlanPolicy {
   157	    /** Throws INVALID_REQUEST if the plan cannot be used for this room and stay. */
   158	    void validate(Room room, LocalDate checkIn, LocalDate checkOut);
   159	
   160	    Price calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut);
   161	
