   164	package hotel.reservations;
   165	
   166	import hotel.rooms.Room;
   167	import java.math.BigDecimal;
   168	import java.math.RoundingMode;
   169	import java.time.LocalDate;
   170	import java.time.Month;
   171	
   172	/**
   173	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
   174	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
   175	 * (half-even) at every step.
   176	 */
   177	public final class PriceCalculator {
   178	
   179	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
   180	
   181	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
   182	        RatePlanPolicy policy = RatePlanPolicies.forPlan(ratePlan, companyCode);
   183	        policy.validate(room, checkIn, checkOut);
   184	        return policy.calculatePrice(room, checkIn, checkOut);
   185	    }
   186	
   187	    /** Sums nightly rates (with high-season surcharge) and applies a percentage discount. */
   188	    static Price nightlySubtotal(Room room, LocalDate checkIn, LocalDate checkOut, BigDecimal discountRate) {
   189	        int nights = 0;
   190	        BigDecimal subtotal = cents(BigDecimal.ZERO);
   191	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
   192	            subtotal = subtotal.add(nightPrice(room, night));
   193	            nights++;
   194	        }
   195	        BigDecimal discount = cents(subtotal.multiply(discountRate));
   196	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
   197	    }
   198	
   199	    static BigDecimal nightPrice(Room room, LocalDate night) {
   200	        BigDecimal nightlyRate = room.nightlyRate();
   201	        if (isHighSeason(night)) {
   202	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
   203	        }
   204	        return cents(nightlyRate);
   205	    }
   206	
   207	    /** High season: from December 15 to the end of February, and the whole of July. */
   208	    static boolean isHighSeason(LocalDate date) {
   209	        Month month = date.getMonth();
   210	        return month == Month.JANUARY
   211	                || month == Month.FEBRUARY
   212	                || month == Month.JULY
   213	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
   214	    }
   215	
   216	    static BigDecimal cents(BigDecimal value) {
   217	        return value.setScale(2, RoundingMode.HALF_EVEN);
   218	    }
   219	}

