    19	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    20	        this.rooms = rooms;
    21	        this.store = store;
    22	        this.priceCalculator = priceCalculator;
    23	        this.emailSender = emailSender;
    24	    }
    25	
    26	    public synchronized Reservation create(NewReservation request) {
    27	        if (!request.checkOut().isAfter(request.checkIn())) {
    28	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    29	        }
    30	        if (request.guests() < 1) {
    31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    32	        }
    33	        Room room = rooms.find(request.roomNumber())
    34	                .orElseThrow(() -> new HotelException(
    35	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    36	        if (request.guests() > room.capacity()) {
    37	            throw new HotelException(
    38	                    ErrorCode.CAPACITY_EXCEEDED,
    39	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    40	        }
    41	        boolean roomTaken = store.all().stream()
    42	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    43	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    44	        if (roomTaken) {
    45	            throw new HotelException(
    46	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    47	        }
    48	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
    49	        Reservation reservation = new Reservation(store.nextId(), request, price);
    50	        store.save(reservation);
    51	        return reservation;
    52	    }
    53	
    54	    public Reservation find(long reservationId) {
    55	        return store.find(reservationId)
    56	                .orElseThrow(() -> new HotelException(
    57	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    58	    }
    59	
    60	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    61	    public synchronized Reservation confirm(long reservationId) {
    62	        Reservation reservation = find(reservationId);
    63	        if (reservation.status() != ReservationStatus.PENDING) {
    64	            throw notAllowed(reservation, "confirm");
    65	        }
    66	        reservation.confirmPayment();
    67	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    68	        emailSender.send(
    69	                reservation.guest().email(),
    70	                "Reserva confirmada - " + HOTEL_NAME,
    71	                confirmationEmailBody(reservation, receipt));
    72	        return reservation;
    73	    }
    74	
    75	    /**
    76	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    77	     * reservation was never paid, so nothing comes back).
    78	     */
    79	    public synchronized Reservation cancel(long reservationId) {
    80	        Reservation reservation = find(reservationId);
    81	        if (reservation.status() != ReservationStatus.PENDING
    82	                && reservation.status() != ReservationStatus.CONFIRMED) {
    83	            throw notAllowed(reservation, "cancel");
    84	        }
    85	        BigDecimal refund = RatePlanPolicies.forPlan(reservation.ratePlan(), reservation.companyCode())
    86	                .calculateRefund(reservation.amountPaid());
    87	        reservation.cancel(refund);
    88	        return reservation;
    89	    }
    90	
    91	    public synchronized Reservation checkIn(long reservationId) {
    92	        Reservation reservation = find(reservationId);
    93	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    94	            throw notAllowed(reservation, "check in");
    95	        }
    96	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    97	        return reservation;
    98	    }
    99	
   100	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   101	    public synchronized ReservationReceipt checkOut(long reservationId) {
   102	        Reservation reservation = find(reservationId);
   103	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   104	            throw notAllowed(reservation, "check out");
   105	        }
   106	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   107	        return new ReservationReceipt(reservation, roomOf(reservation));
   108	    }
   109	
   110	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   111	    public ReservationReceipt receiptCopy(long reservationId) {
   112	        Reservation reservation = find(reservationId);
   113	        if (!reservation.isPaid()) {
   114	            throw notAllowed(reservation, "issue a receipt for");
   115	        }
   116	        return new ReservationReceipt(reservation, roomOf(reservation));
   117	    }
   118	
   119	    private Room roomOf(Reservation reservation) {
